:root, [data-trm-theme="light"], [data-trm-theme="dark"] {
  --trm-primary: #075985;
  --trm-primary-contrast: #fff;
  --trm-radius: .75rem;
  --trm-font-sans: system-ui, sans-serif;
}

.brand-button {
  --trm-btn-bg: #075985;
  --trm-btn-border: #075985;
  --trm-btn-color: #fff;
}

import 'tremplin/css'
import Collapse from 'tremplin/collapse'

const panel = document.querySelector('#details')
if (panel) {
  const instance = Collapse.getOrCreateInstance(panel)
  await instance.show()
  // Await transitions before the next dependent state change.
  await instance.hide()
}

import { Collapse } from './dist/js/tremplin.bundle.min.js'

const panel = document.querySelector('#details')
const instance = Collapse.getOrCreateInstance(panel)
instance.show()

import { Collapse } from './dist/js/tremplin.bundle.min.js'

const panel = document.querySelector('#details')
panel.addEventListener('show.trm.collapse', event => {
  if (panel.dataset.locked === 'true') event.preventDefault()
})
panel.addEventListener('shown.trm.collapse', () => {
  console.log('Details are now open')
})

import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'

const manifest = JSON.parse(readFileSync('integrity.json', 'utf8'))
const actual = 'sha384-' + createHash('sha384')
  .update(readFileSync('tremplin.min.css'))
  .digest('base64')
if (actual !== manifest.assets['css/tremplin.min.css'].integrity) {
  throw new Error('Integrity mismatch: do not use this file')
}
console.log('Verified Tremplin', manifest.version)

